            if ($target.attr('data-step_index') === '1') {
                // Only set date to today if no date is already selected (e.g., when editing an existing booking)
                if (!$selectDate.val()) {
                    const todayMoment = moment();
                    App.Utils.UI.setDateTimePickerValue($selectDate, todayMoment.toDate());
                }
                const selectedDateString = $selectDate.val()
                    ? moment($selectDate.val()).format('YYYY-MM-DD')
                    : moment().format('YYYY-MM-DD');
                App.Http.Booking.getUnavailableDates(
                    $selectProvider.val(),
                    $selectService.val(),
                    selectedDateString,
                );
            }
